'use strict';

// Bangs: `!yt lofi` searches YouTube directly. This is the one parser,
// resolver and picker matcher that main (require) and the overlay (<script>,
// window.Bangs) share, so Enter in main and the hint row in the Island cannot
// disagree. Pure and self-contained: no require, no Electron, no Node API, no
// DOM, so another browser core takes it unchanged. Spec:
// docs/superpowers/specs/2026-10-16-bangs-design.md.
//
// Catalog entries (generated by bangs/build.mjs) are
//   [code, aliases, name, domain, template, encoding, home]
// where template holds %s, encoding is ENCODE | PLUS bits, and home is the
// complete address an empty query opens. Custom bangs are { code, name,
// template }; they encode with the defaults and open their origin when empty.
// Template validation happens before a template reaches this module (at build
// for built-ins, in settings for custom bangs); this module only substitutes.
(function (root) {
  const BANG_CODE = /^[a-z0-9][a-z0-9_-]{0,31}$/i;
  const ENCODE = 1;
  const PLUS = 2;
  const DEFAULT_ENCODING = ENCODE | PLUS;
  const MAX_ROWS = 8;

  function isBangCode(value) {
    return typeof value === 'string' && BANG_CODE.test(value);
  }

  /** The bang token in `text`: `!code` as the first or the last
   * whitespace-delimited token. The first token wins. */
  function parseBang(text) {
    if (typeof text !== 'string') return null;
    const trimmed = text.trim();
    if (!trimmed) return null;
    const tokens = trimmed.split(/\s+/);
    const first = tokens[0];
    if (first.startsWith('!') && isBangCode(first.slice(1))) {
      return { code: first.slice(1).toLowerCase(), query: tokens.slice(1).join(' '), position: 'start' };
    }
    const last = tokens[tokens.length - 1];
    if (tokens.length > 1 && last.startsWith('!') && isBangCode(last.slice(1))) {
      return { code: last.slice(1).toLowerCase(), query: tokens.slice(0, -1).join(' '), position: 'end' };
    }
    return null;
  }

  function encodeQuery(query, encoding) {
    const bits = Number.isInteger(encoding) ? encoding : DEFAULT_ENCODING;
    let out = String(query);
    if (bits & ENCODE) out = encodeURIComponent(out);
    if (bits & PLUS) out = bits & ENCODE ? out.replace(/%20/g, '+') : out.replace(/ /g, '+');
    return out;
  }

  // Catalog arrays are indexed once; the index lives beside the array.
  const indexes = new WeakMap();
  function indexOf(catalog) {
    let index = indexes.get(catalog);
    if (index) return index;
    index = new Map();
    for (const entry of catalog) {
      // The first definition of a code or alias wins; the build keeps them
      // unique, and this keeps lookups deterministic if it ever does not.
      if (!index.has(entry[0])) index.set(entry[0], entry);
      for (const alias of entry[1]) if (!index.has(alias)) index.set(alias, entry);
    }
    indexes.set(catalog, index);
    return index;
  }

  function templateHost(template) {
    try {
      return new URL(template.replace('%s', 'x')).host;
    } catch {
      return '';
    }
  }

  function templateOrigin(template) {
    try {
      return `${new URL(template.replace('%s', 'x')).origin}/`;
    } catch {
      return '';
    }
  }

  function customRecord(bang) {
    return {
      code: bang.code,
      name: bang.name,
      domain: templateHost(bang.template),
      template: bang.template,
      encoding: DEFAULT_ENCODING,
      home: templateOrigin(bang.template),
      custom: true,
    };
  }

  function catalogRecord(entry) {
    return { code: entry[0], name: entry[2], domain: entry[3], template: entry[4], encoding: entry[5], home: entry[6], custom: false };
  }

  /** The bang `code` names: a custom bang first (it shadows exactly that code
   * or alias), then the catalog by primary code or alias. */
  function findBang(code, catalog, customBangs) {
    if (!isBangCode(code)) return null;
    const lower = code.toLowerCase();
    const custom = (customBangs || []).find((b) => b && b.code === lower);
    if (custom) return customRecord(custom);
    const entry = indexOf(catalog || []).get(lower);
    return entry ? catalogRecord(entry) : null;
  }

  function resolveBang(text, catalog, customBangs) {
    const parsed = parseBang(text);
    if (!parsed) return null;
    const bang = findBang(parsed.code, catalog, customBangs);
    if (!bang) return null;
    const url = parsed.query
      ? bang.template.replace('%s', () => encodeQuery(parsed.query, bang.encoding))
      : bang.home;
    return { url, name: bang.name, code: bang.code, query: parsed.query };
  }

  function pickRow(section, record) {
    return { section, code: record.code, name: record.name, domain: record.domain, custom: record.custom };
  }

  /** Picker rows for `prefix` (the text after `!`): recent, then popular,
   * then every other code starting with the prefix (shorter first, then
   * alphabetical), then names containing it. Each bang once, by primary
   * code; the exact match is left out because the caller shows it as the
   * hint row. */
  function matchBangs(prefix, catalog, customBangs, recent, popular) {
    const needle = String(prefix || '').toLowerCase();
    const rows = [];
    const seen = new Set();
    const exact = needle ? findBang(needle, catalog, customBangs) : null;
    if (exact) seen.add(exact.code);
    const matchesCode = (record, codes) => codes.some((c) => c.startsWith(needle));
    // `!` alone lists every recent and popular bang under its foldable
    // headers; only a filtered list is capped.
    const push = (section, record) => {
      if ((needle && rows.length >= MAX_ROWS) || seen.has(record.code)) return;
      seen.add(record.code);
      rows.push(pickRow(section, record));
    };

    for (const code of recent || []) {
      const record = findBang(code, catalog, customBangs);
      if (record && (!needle || record.code.startsWith(needle))) push('recent', record);
    }
    for (const code of popular || []) {
      const record = findBang(code, catalog, customBangs);
      if (record && (!needle || record.code.startsWith(needle))) push('popular', record);
    }
    if (!needle) return rows;

    const candidates = [];
    const shadowed = new Set();
    for (const bang of customBangs || []) {
      if (!bang || !isBangCode(bang.code)) continue;
      candidates.push({ record: customRecord(bang), codes: [bang.code] });
      shadowed.add(bang.code);
    }
    // A catalog entry whose primary code a custom bang took is gone from the
    // picker (its row would fill a code that now means the custom bang); a
    // taken alias only stops matching.
    for (const entry of catalog || []) {
      if (shadowed.has(entry[0])) continue;
      candidates.push({ record: catalogRecord(entry), codes: [entry[0], ...entry[1].filter((alias) => !shadowed.has(alias))] });
    }
    // The person's own bangs lead the section whatever their code length, so
    // the row cap never hides them behind catalog entries.
    const byCode = candidates
      .filter((c) => matchesCode(c.record, c.codes))
      .sort((a, b) => Number(b.record.custom) - Number(a.record.custom)
        || a.record.code.length - b.record.code.length
        || (a.record.code < b.record.code ? -1 : a.record.code > b.record.code ? 1 : 0));
    for (const c of byCode) push('all', c.record);
    if (rows.length < MAX_ROWS) {
      for (const c of candidates) {
        if (c.record.name.toLowerCase().includes(needle)) push('all', c.record);
      }
    }
    return rows;
  }

  const api = { BANG_CODE, ENCODE, PLUS, DEFAULT_ENCODING, isBangCode, parseBang, encodeQuery, findBang, resolveBang, matchBangs };
  if (typeof module !== 'undefined') module.exports = api;
  else root.Bangs = api;
})(typeof window !== 'undefined' ? window : globalThis);
